create table candidate_profiles (total_experience_months integer, confirmed_at timestamp(6), created_at timestamp(6) not null, updated_at timestamp(6) not null, id uuid not null, resume_id uuid not null unique, current_company varchar(255), current_job_role varchar(255), email varchar(255), full_name varchar(255), phone varchar(255), professional_summary TEXT, professional_title varchar(255), status varchar(255) not null check ((status in ('PROCESSING','REVIEW_REQUIRED','CONFIRMED','PARSING_FAILED'))), target_role varchar(255), primary key (id));
create table candidate_projects (current_project boolean not null, end_date date, start_date date, candidate_profile_id uuid not null, id uuid not null, business_impact TEXT, candidate_role varchar(255), domain varchar(255), project_description TEXT, project_name varchar(255) not null, responsibilities TEXT, primary key (id));
create table candidate_skills (verified boolean not null, years_of_experience numeric(5,2), candidate_profile_id uuid not null, id uuid not null, category varchar(255) not null check ((category in ('PROGRAMMING_LANGUAGE','BACKEND','FRONTEND','DATABASE','CACHE','MESSAGING','CLOUD','DEVOPS','TESTING','SYSTEM_DESIGN','TOOL','OTHER'))), evidence TEXT, proficiency varchar(255) check ((proficiency in ('BEGINNER','INTERMEDIATE','ADVANCED','EXPERT'))), skill_name varchar(255) not null, source varchar(255) not null check ((source in ('RESUME','USER_ADDED','AI_INFERRED'))), primary key (id));
create table interview_questions (answered boolean, display_order integer, score integer, answered_at timestamp(6), created_at timestamp(6), id uuid not null, interview_session_id uuid, question_text varchar(3000) not null, expected_answer varchar(5000), user_answer varchar(5000), ai_feedback TEXT, difficulty varchar(255), improved_answer TEXT, question_type varchar(255), primary key (id));
create table interview_sessions (answered_questions integer, overall_score integer, total_questions integer, completed_at timestamp(6), created_at timestamp(6), started_at timestamp(6), id uuid not null, user_id uuid, ai_summary_feedback varchar(5000), experience_level varchar(255), status varchar(255) check ((status in ('CREATED','IN_PROGRESS','COMPLETED','CANCELLED'))), target_role varchar(255), title varchar(255), topic varchar(255), primary key (id));
create table preparation_answers (created_at timestamp(6) not null, updated_at timestamp(6) not null, id uuid not null, question_id uuid not null unique, business_impact TEXT, code_example TEXT, common_mistakes TEXT, detailed_answer TEXT, follow_up_questions TEXT, internal_working TEXT, last_user_feedback TEXT, product_company_expectation TEXT, project_usage TEXT, service_company_expectation TEXT, short_answer TEXT, star_answer TEXT, what_not_to_say TEXT, primary key (id));
create table preparation_questions (bookmarked boolean not null, created_at timestamp(6) not null, updated_at timestamp(6) not null, id uuid not null, section_id uuid not null, difficulty varchar(255) not null check ((difficulty in ('BEGINNER','INTERMEDIATE','ADVANCED'))), progress_status varchar(255) not null check ((progress_status in ('NOT_STARTED','IN_PROGRESS','COMPLETED'))), question_text TEXT not null, question_type varchar(255), resume_relevance TEXT, source_project varchar(255), source_skill varchar(255), primary key (id));
create table project_technologies (verified boolean not null, candidate_project_id uuid not null, id uuid not null, technology_name varchar(255) not null, usage_description TEXT, primary key (id));
create table question_bank_questions (display_order integer, created_at timestamp(6) not null, updated_at timestamp(6) not null, id uuid not null, section_id uuid not null, category varchar(255) not null, detailed_answer TEXT, difficulty varchar(255), question_text TEXT not null, short_answer TEXT, primary key (id));
create table question_banks (created_at timestamp(6) not null, generated_at timestamp(6), updated_at timestamp(6) not null, candidate_profile_id uuid not null, id uuid not null, user_id uuid not null, generation_error TEXT, status varchar(255) not null check ((status in ('GENERATING','REVIEW_REQUIRED','READY','GENERATION_FAILED'))), title varchar(255) not null, primary key (id));
create table question_sections (display_order integer, id uuid not null, question_bank_id uuid not null, category varchar(255), section_name varchar(255) not null, primary key (id));
create table resumes (created_at timestamp(6) not null, file_size bigint not null, parsed_at timestamp(6), updated_at timestamp(6) not null, id uuid not null, user_id uuid not null, content_type varchar(255) not null, original_file_name varchar(255) not null, parsing_error TEXT, status varchar(255) not null check ((status in ('UPLOADED','PARSING','PARSED','PARSING_FAILED','ARCHIVED','PROCESSING'))), storage_key varchar(255) not null unique, stored_file_name varchar(255) not null, primary key (id));
create table users (created_at timestamp(6), id uuid not null, email varchar(255) not null unique, full_name varchar(255), password varchar(255), role varchar(255) check ((role in ('USER','ADMIN'))), primary key (id));
alter table if exists candidate_profiles add constraint FKcmmidro749lypwar83kjqtres foreign key (resume_id) references resumes;
alter table if exists candidate_projects add constraint FKc4w0amy734ihv8p3jemhqjc10 foreign key (candidate_profile_id) references candidate_profiles;
alter table if exists candidate_skills add constraint FKth710w3978vqyonpto6hwyper foreign key (candidate_profile_id) references candidate_profiles;
alter table if exists interview_questions add constraint FKglpb7ukxxh1mc0aclx5hksqoi foreign key (interview_session_id) references interview_sessions;
alter table if exists interview_sessions add constraint FKoa5rgsdu7rqa8y74yph1fuqe5 foreign key (user_id) references users;
