alter table if exists preparation_questions add constraint FK1wrdj54llvwa2v1k5ebi7yrdd foreign key (section_id) references question_sections;
alter table if exists project_technologies add constraint FKkg6rmi50wupo7s00qi12mfdgn foreign key (candidate_project_id) references candidate_projects;
alter table if exists question_bank_questions add constraint FKr8asehukpyi4bw70vcjxdv80x foreign key (section_id) references question_sections;
alter table if exists question_banks add constraint FKrtdp9jr56am0ov3jeq1dmimx9 foreign key (candidate_profile_id) references candidate_profiles;
alter table if exists question_banks add constraint FKqyi7qfkapx8kv4vfkpifubta6 foreign key (user_id) references users;
